/* UI and tree drawing; inference is in tree.js. */
'use strict';
let model;
const $=id=>document.getElementById(id);
const NS='http://www.w3.org/2000/svg';
function svgEl(tag,attrs,text){const el=document.createElementNS(NS,tag);for(const [key,value]of Object.entries(attrs))el.setAttribute(key,value);if(text!==undefined)el.textContent=text;return el;}
function drawTree(result){
 const svg=$('tree-graph');svg.replaceChildren();
 const positions=new Map();let leaves=0,maxDepth=0;
 function layout(node,depth){maxDepth=Math.max(maxDepth,depth);let x;if(node.is_leaf)x=leaves++;else{const xs=Object.values(node.children).map(child=>layout(child,depth+1));x=(xs[0]+xs.at(-1))/2;}positions.set(node.id,{x,y:depth});return x;}
 layout(model.tree,0);
 const width=Math.max(950,leaves*175),height=(maxDepth+1)*160+80;svg.setAttribute('viewBox','0 0 '+width+' '+height);
 for(const p of positions.values()){p.x=95+p.x*(width-190)/Math.max(leaves-1,1);p.y=65+p.y*160;}
 const active=new Set([...result.path.map(step=>step.node_id),result.leaf_id]);
 function edges(node){const p=positions.get(node.id);for(const [value,child]of Object.entries(node.children)){const q=positions.get(child.id),used=result.path.some(step=>step.node_id===node.id&&step.value===value&&!step.fallback);svg.append(svgEl('path',{d:'M '+p.x+' '+(p.y+43)+' L '+q.x+' '+(q.y-43),class:used?'active-edge':'edge'}));const tx=(p.x+q.x)/2,ty=(p.y+q.y)/2;svg.append(svgEl('rect',{x:tx-43,y:ty-12,width:86,height:24,fill:'white',rx:5}));svg.append(svgEl('text',{x:tx,y:ty+4,'text-anchor':'middle',fill:used?'#975d0b':'#536971'},value));edges(child);}}
 edges(model.tree);
 function nodes(node){const p=positions.get(node.id),used=active.has(node.id),color=node.is_leaf?(node.prediction==='Yes'?'#237658':'#ac4653'):'#294a53';svg.append(svgEl('rect',{x:p.x-78,y:p.y-43,width:156,height:86,rx:12,fill:used?'#fff3d5':node.is_leaf?'#f3f7f4':'#edf3f1',stroke:used?'#c98217':color,'stroke-width':used?3:1.5}));const lines=[node.is_leaf?'Play = '+node.prediction:node.feature,'H = '+node.entropy.toFixed(3)+' | n = '+node.sample_count,'Yes '+node.class_counts.Yes+' / No '+node.class_counts.No];if(!node.is_leaf)lines.push('Gain = '+node.gain.toFixed(3));lines.forEach((line,i)=>svg.append(svgEl('text',{x:p.x,y:p.y-21+i*17,'text-anchor':'middle',fill:color,'font-weight':i===0?700:400},line)));Object.values(node.children).forEach(nodes);}
 nodes(model.tree);
}
function update(){try{const values=Object.fromEntries(model.features.map(f=>[f,$(f).value])),result=DecisionTree.predict(values,model);$('error').textContent='';$('result').replaceChildren();$('result').append(document.createTextNode('Prediction'));const answer=document.createElement('strong');answer.textContent=result.label==='Yes'?'Yes, play tennis':'No, do not play';$('result').append(answer);$('result').append(document.createTextNode(result.path.map(s=>s.feature+' = '+s.value).join(' → ')+(result.fallback?' → majority fallback':'')));$('path').replaceChildren();for(const step of result.path){const li=document.createElement('li');li.textContent=step.feature+' = '+step.value+'. Selected gain: '+step.gain.toFixed(3)+' bits.'+(step.fallback?' Unseen branch: use this node’s majority.':'');$('path').append(li);}const li=document.createElement('li');li.textContent='Final answer: Play = '+result.label;$('path').append(li);drawTree(result);}catch(error){$('error').textContent=error.message;}}
$('prediction-form').addEventListener('submit',event=>{event.preventDefault();update();});
$('prediction-form').addEventListener('change',()=>{if(model)update();});
$('pdf-example').addEventListener('click',()=>{for(const [key,value]of Object.entries({Outlook:'Sunny',Temp:'Mild',Humidity:'High',Wind:'Strong'}))$(key).value=value;update();});
$('download-graph').addEventListener('click',()=>{const copy=$('tree-graph').cloneNode(true);copy.setAttribute('xmlns',NS);const style=svgEl('style',{},'text{font-family:Arial,sans-serif;font-size:13px}.edge{stroke:#b9c9c3;stroke-width:2;fill:none}.active-edge{stroke:#c98217;stroke-width:4;fill:none}');copy.prepend(style);const url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(copy)],{type:'image/svg+xml'}));const link=document.createElement('a');link.href=url;link.download='id3-decision.svg';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
fetch('model.json').then(r=>{if(!r.ok)throw Error('Cannot load model. Run python train_model.py.');return r.json();}).then(data=>{
 model=data;const table=document.createElement('table');const header=table.createTHead().insertRow();for(const title of ['Attribute','Information gain (bits)']){const cell=document.createElement('th');cell.textContent=title;header.append(cell);}const body=table.createTBody();for(const [feature,gain]of Object.entries(model.tree.gains).sort((a,b)=>b[1]-a[1])){const row=body.insertRow();row.insertCell().textContent=feature;row.insertCell().textContent=gain.toFixed(6);}if(!body.rows.length){const row=body.insertRow();row.insertCell().textContent='Root stopped by training parameters';}$('gains').append(table);
 const dataHead=$('dataset').createTHead().insertRow();for(const key of ['Day',...model.features,'Play']){const cell=document.createElement('th');cell.textContent=key;dataHead.append(cell);}const dataBody=$('dataset').createTBody();model.training_examples.forEach((example,i)=>{const row=dataBody.insertRow();for(const value of [i+1,...model.features.map(f=>example[f]),example.Play])row.insertCell().textContent=value;});$('accuracy').textContent='Training accuracy: '+(model.training_accuracy*100).toFixed(1)+'%. This is a reconstruction of the lecture dataset, not a held-out evaluation.';$('parameters').textContent='Current training parameters: '+JSON.stringify(model.parameters);for(const button of document.querySelectorAll('button'))button.disabled=false;update();
}).catch(error=>{$('error').textContent=error.message;$('result').textContent='Model unavailable';});
